/**
 * Task management, parsing from handwriting/voice, and priority ordering.
 */

export type Priority = 'high' | 'medium' | 'low';

export interface TaskItem {
  id: string;
  text: string;
  completed: boolean;
  priority: Priority;
  dueDate?: string; // YYYY-MM-DD
  notebookId?: string;
  noteId?: string;
  createdAt: number;
  completedAt?: number;
}

export interface TaskStats {
  total: number;
  completed: number;
  pending: number;
  percent: number;
}

/**
 * Extracts action items / tasks from text generated by handwriting OCR or voice transcripts.
 */
export function extractTasksFromText(rawText: string, defaultPriority: Priority = 'medium'): TaskItem[] {
  if (!rawText || !rawText.trim()) return [];

  const lines = rawText.split('\n');
  const tasks: TaskItem[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    // Detect markdown checkbox: - [ ] or - [x]
    const checkboxMatch = trimmed.match(/^[-*•]\s*\[([ xX])\]\s*(.*)$/);
    if (checkboxMatch) {
      const isCompleted = checkboxMatch[1].toLowerCase() === 'x';
      const text = checkboxMatch[2].trim();
      if (text) {
        tasks.push({
          id: `task-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
          text,
          completed: isCompleted,
          priority: defaultPriority,
          createdAt: Date.now(),
        });
      }
      continue;
    }

    // Detect standard bullet point or numbered item: - Item, * Item, 1. Item
    const bulletMatch = trimmed.match(/^[-*•\d.]+\s+(.*)$/);
    if (bulletMatch) {
      const text = bulletMatch[1].trim();
      if (text) {
        tasks.push({
          id: `task-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
          text,
          completed: false,
          priority: defaultPriority,
          createdAt: Date.now(),
        });
      }
      continue;
    }

    // Detect action keywords in Spanish (comprar, revisar, llamar, enviar, terminar, preparar)
    const actionKeyword = /^(comprar|revisar|llamar|enviar|terminar|preparar|estudiar|hacer|pagar)\b/i.test(trimmed);
    if (actionKeyword && trimmed.length < 120) {
      tasks.push({
        id: `task-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
        text: trimmed,
        completed: false,
        priority: defaultPriority,
        createdAt: Date.now(),
      });
    }
  }

  return tasks;
}

/**
 * Calculates task completion statistics.
 */
export function calculateTaskStats(tasks: TaskItem[]): TaskStats {
  const total = tasks.length;
  const completed = tasks.filter((t) => t.completed).length;
  const pending = total - completed;
  const percent = total > 0 ? Math.round((completed / total) * 100) : 0;

  return { total, completed, pending, percent };
}

/**
 * Sorts tasks: uncompleted first, then by priority (high > medium > low), then dueDate.
 */
export function sortTasks(tasks: TaskItem[]): TaskItem[] {
  const priorityWeight: Record<Priority, number> = {
    high: 3,
    medium: 2,
    low: 1,
  };

  return [...tasks].sort((a, b) => {
    // 1. Incomplete first
    if (a.completed !== b.completed) {
      return a.completed ? 1 : -1;
    }

    // 2. Priority
    const weightDiff = priorityWeight[b.priority] - priorityWeight[a.priority];
    if (weightDiff !== 0) return weightDiff;

    // 3. Due date
    if (a.dueDate && b.dueDate) {
      return a.dueDate.localeCompare(b.dueDate);
    }
    if (a.dueDate && !b.dueDate) return -1;
    if (!a.dueDate && b.dueDate) return 1;

    // 4. Creation date
    return b.createdAt - a.createdAt;
  });
}
